  "\uC7A0\uAE08=\uCE78\uB9C8\uB2E4 \uC7A0\uADF8\uC9C0 \uB9C8. \uACE1 \uBAA9\uB85D\uACFC \uACB0\uACFC \uD56D\uBAA9 \uC790\uBB3C\uC1E0\uB294 \uB450\uC9C0 \uB9C8. \uC790\uB3D9\uC73C\uB85C \uC7A0\uADF8\uC9C0 \uB9C8.",
  "\uBD80\uC2E4\uCE78=\uD655\uC815\uACE1\uC740 \uAC74\uB108\uB6F4\uB2E4. \uBE48 \uCE78\uC740 \uC0DD\uC131, \uB300\uCDA9 \uC4F4 \uCE78\uC740 \uC7AC\uC0DD\uC131, \uBD80\uC2E4\uD55C \uCE78\uC740 \uBCF4\uC644. \uC798 \uB41C \uCE78\uC740 \uB2E4\uC2DC \uC4F0\uC9C0 \uB9C8.",
  "\uC21C\uC11C=EP \uBC88\uD638\uC21C. \uD55C \uACE1\uC5D0 \uB4E4\uC5B4\uAC00\uBA74 \uADF8 \uACE1\uC758 \uBAA8\uB4E0 \uD56D\uBAA9\uC744 \uB2E4 \uCC98\uB9AC\uD55C \uB4A4\uC5D0 \uB2E4\uC74C \uACE1\uC73C\uB85C \uB118\uC5B4\uAC04\uB2E4. \uD56D\uBAA9 \uD558\uB098\uB9CC \uD558\uACE0 \uB2E4\uC74C \uACE1\uC73C\uB85C \uB118\uAE30\uC9C0 \uB9C8. \uC0AC\uC6A9\uC790\uAC00 \uACE0\uB978 \uBC94\uC704\uB9CC. \uB2E4\uB978 \uC7A5\uB974\uB85C \uB118\uC5B4\uAC00\uC9C0 \uB9C8.",
  "\uC6B0\uC120=\uACB0\uACFC\uCC3D \uCC44\uC6B0\uAE30 \uC21C\uC11C\uB294 \uD655\uC815 \uC81C\uBAA9, \uAC00\uC0AC, \uC720\uD29C\uBE0C \uC81C\uBAA9, \uC601\uC0C1 \uC124\uBA85\uB780, \uCEE4\uBBA4\uB2C8\uD2F0 \uAE00, \uADF8 \uB2E4\uC74C \uB098\uBA38\uC9C0\uB2E4. \uACB0\uACFC\uCC3D\uC758 \uC81C\uBAA9\uC740 \uD655\uC815 \uC81C\uBAA9\uC774\uB2E4. \uC81C\uBAA9 \uACE0\uC815\uC774\uB77C\uACE0 \uC6D0\uACE1 \uC81C\uBAA9\uC744 \uBCF5\uC0AC\uD558\uC9C0 \uB9C8. \uC0AC\uC6A9\uC790\uAC00 \uD655\uC815 \uC81C\uBAA9\uC744 \uBC14\uAFB8\uBA74 \uACE0\uC815\uC774\uB4E0 \uBCC0\uD658\uC774\uB4E0 \uADF8 \uC81C\uBAA9\uC744 \uB530\uB978\uB2E4. \uAC00\uC0AC\uB294 \uC0C1\uB2E8 \uC6D0\uACE1 \uAC00\uC0AC\uB97C \uC7A5\uB974 \uAC1C\uC0AC \uADDC\uCE59\uC73C\uB85C \uC4F4\uB2E4.",
  "\uAC1C\uBCC4\uC7AC\uC0DD\uC131=\uACB0\uACFC\uCC3D\uC5D0\uC11C \uD55C \uCE78\uC758 \uC7AC\uC0DD\uC131\uC740 \uADF8 \uCE78\uB9CC \uB2E4\uC2DC \uC4F0\uACE0 \uADF8 \uCE78\uC744 \uC800\uC7A5\uD55C\uB2E4. \uB2E4\uB978 \uCE78\uC740 \uC720\uC9C0\uD55C\uB2E4. \uC810\uC218\uAC00 \uB0AE\uAC70\uB098 \uC9E7\uC544\uB3C4 \uADF8 \uCE78\uC740 \uC800\uC7A5\uD55C\uB2E4. \uC800\uC7A5\uC774 \uC548 \uB418\uBA74 \uC9C0\uAE08 \uD654\uBA74\uC5D0 \uC774\uC720\uB97C \uC801\uB294\uB2E4. \uD655\uC815\uACE1\uC740 \uB2E4\uC2DC \uC4F0\uC9C0 \uB9C8. \uCD9C\uB825 \uC2A4\uC704\uCE58\uB97C \uAEBC\uB3C4 \uC774\uBBF8 \uC800\uC7A5\uB41C \uAC00\uC0AC\xB7\uC218\uB178\xB7\uC694\uC57D\xB7\uC124\uBA85\uC740 \uC9C0\uC6B0\uC9C0 \uB9C8. \uD655\uC815\uACE1 \uBCF8\uBB38\uC740 \uC0AC\uC6A9\uC790\uAC00 \uADF8 \uCE78\uC744 \uC9C1\uC811 \uACE0\uCE5C \uB4A4\uC5D0\uB9CC \uBC14\uAFBC\uB2E4. \uC81C\uBAA9 \uACE0\uC815\uC774\uB77C\uACE0 \uD655\uC815 \uC81C\uBAA9\uC744 \uC6D0\uACE1 \uC81C\uBAA9\uC73C\uB85C \uB418\uB3CC\uB9AC\uC9C0 \uB9C8. \uC0AC\uC6A9\uC790\uAC00 \uBC14\uAFBC \uD655\uC815 \uC81C\uBAA9\uC740 \uACE0\uC815\uC774\uB4E0 \uBCC0\uD658\uC774\uB4E0 \uC720\uC9C0\uD55C\uB2E4. \uAC00\uC0AC \uC7AC\uC0DD\uC131\uC740 \uC0C1\uB2E8 \uC6D0\uACE1 \uAC00\uC0AC\uB97C \uC7A5\uB974 \uAC1C\uC0AC \uADDC\uCE59\uC73C\uB85C \uB2E4\uC2DC \uC4F4\uB2E4. \uB2E4\uB978 \uACE1 \uAC00\uC0AC \uC704\uC5D0 \uC774 \uACE1 \uC81C\uBAA9\uC744 \uB36E\uC9C0 \uB9C8. \uD654\uBA74\uC6A9 \uBE48 \uACB0\uACFC \uC704\uC5D0 \uD55C \uCE78\uB9CC \uB36E\uC5B4 \uC800\uC7A5\uD558\uC9C0 \uB9C8.",
  "\uC7AC\uC0DD\uC131\uCDE8\uC18C=\uACB0\uACFC\uCC3D \uD56D\uBAA9\uC744 \uC7AC\uC0DD\uC131\uD558\uB294 \uB3D9\uC548 \uADF8 \uBC84\uD2BC\uC774 \uB3CC\uBA74 \uB2E4\uC2DC \uB20C\uB7EC \uC0DD\uC131\uC744 \uCDE8\uC18C\uD55C\uB2E4. \uCDE8\uC18C\uD558\uBA74 \uADF8 \uCE78\uC744 \uC800\uC7A5\uD558\uC9C0 \uB9C8. \uB2E4\uB978 \uCE78\uC740 \uADF8\uB300\uB85C \uB454\uB2E4.",
  "\uC5F0\uACB0=\uAC80\uC5F4\uC740 \uADF8 EP \uACB0\uACFC\uCC3D \uC0C1\uB2E8\uC758 \uC6D0\uACE1 \uC81C\uBAA9\xB7\uAC00\uC0AC\uC640 \uACF5\uD1B5\xB7\uC7A5\uB974 \uADDC\uCE59\uC744 \uAE30\uC900\uC73C\uB85C \uD55C\uB2E4. \uADF8\uC640 \uB2E4\uB974\uAC8C \uB9CC\uB4E0 \uD56D\uBAA9\uC740 \uC798\uBABB\uB41C \uACB0\uACFC\uB2E4.",
  "\uCD9C\uCC98=\uADF8 EP \uACB0\uACFC\uAC12\uC740 \uADF8 EP \uD398\uC774\uC9C0\uC5D0\uC11C\uB9CC \uC0DD\uC131\uD55C\uB2E4. \uB2E4\uB978 EP \uACE1\uC758 \uACB0\uACFC\uAC12\uC744 \uAC00\uC838\uC624\uBA74 \uC798\uBABB\uB41C \uC5F0\uACB0\uC774\uB2E4. \uADF8 \uAC12\uC740 \uC774 \uD398\uC774\uC9C0\uC5D0\uC11C\uB9CC \uC9C0\uC6B4\uB2E4. \uAC00\uC838\uC628 \uACF3\uC758 \uAC12\uC740 \uC9C0\uC6B0\uC9C0 \uB9C8.",
