  "\uACE0\uC815\uC81C\uBAA9=\uACB0\uACFC\uCC3D\uC758 \uC81C\uBAA9\uC740 \uD655\uC815 \uC81C\uBAA9\uC774\uB2E4. \uC81C\uBAA9 \uACE0\uC815\uC774\uB77C\uACE0 \uC6D0\uACE1 \uC81C\uBAA9\uC744 \uBCF5\uC0AC\uD558\uC9C0 \uB9C8. \uC0AC\uC6A9\uC790\uAC00 \uBC14\uAFBC \uD655\uC815 \uC81C\uBAA9\uC740 \uACE0\uC815\uC774\uB4E0 \uBCC0\uD658\uC774\uB4E0 \uC720\uC9C0\uD55C\uB2E4.",
  "\uC11E\uC9C0\uB9C8=\uC774 \uACE1 \uC81C\uBAA9\uC744 \uB2E4\uB978 \uACE1 \uAC00\uC0AC \uC704\uC5D0 \uB36E\uC5B4 \uC800\uC7A5\uD558\uC9C0 \uB9C8. \uAC00\uC0AC\uAC00 \uB2E4\uB978 \uACE1\uC774\uBA74 \uADF8 \uBCF8\uBB38\uC740 \uC774 \uD398\uC774\uC9C0\uC5D0 \uB450\uC9C0 \uB9C8."
