  const levelRule = "\uC74C\uB7C9\uAE30\uC900=\uC74C\uC6D0 \uCD9C\uB825\uC740 3\uB2E8\uACC4\uB97C \uB05D\uB0B8 \uB4A4\uC5D0\uB9CC \uC7AC\uC0DD\uD55C\uB2E4. 1\uB2E8\uACC4\uB294 \uB9C8\uC2A4\uD130\uB9C1 Intensity 50\uC73C\uB85C \uAC1C\uC120\uD55C\uB2E4. 2\uB2E8\uACC4\uB294 \uB77C\uC6B0\uB4DC\uB2C8\uC2A4 \uC815\uADDC\uD654 LUFS -14\uB85C \uACE0\uC815\uD55C\uB2E4. 3\uB2E8\uACC4\uB294 Peak -1\uB85C \uACE0\uC815\uD55C\uB2E4. \uC138 \uB2E8\uACC4\uAC00 \uB05D\uB098\uAE30 \uC804\uC5D0\uB294 \uB178\uB798\uB97C \uD2C0\uC9C0 \uB9C8. \uBCF4\uC815\uB418\uC9C0 \uC54A\uC740 \uC18C\uB9AC\uB97C \uB0B4\uC9C0 \uB9C8. \uBCF4\uC815\uB41C \uC18C\uB9AC\uAC00 \uC2E4\uC81C\uB85C \uB098\uC624\uB294 \uB3D9\uC548\uB9CC \uC7AC\uC0DD/\uC77C\uC2DC\uC815\uC9C0 \uBC84\uD2BC\uC744 \uAE08\uC0C9\uC73C\uB85C \uB454\uB2E4. \uC544\uB2C8\uBA74 \uC9C0\uAE08 \uBC84\uD2BC \uC0C9\uC744 \uB454\uB2E4. \uC6D0\uD615 \uCE74\uB4DC\uB294 12\uC2DC\uAC00 \uC911\uC2EC\uC774\uB2E4. \uC67C\uCABD\uC740 \uB9C8\uC2A4\uD130\uB9C1\uC73C\uB85C LUFS\uAC00 \uB192\uC544\uC9C4 \uC218\uCE58\uB97C \uBE68\uAC04\uC0C9\uC73C\uB85C \uADF8\uB9B0\uB2E4. \uC624\uB978\uCABD\uC740 LUFS -14\uB85C \uC870\uC815\uD55C \uAC12\uC744 \uD30C\uB780\uC0C9\uC73C\uB85C \uADF8\uB9B0\uB2E4. \uD53C\uD06C \uC870\uC815\uAC12\uC740 \uC624\uB978\uCABD \uD30C\uB780\uC0C9 \uC704\uC5D0 \uACB9\uCCD0 \uB178\uB780\uC0C9\uC73C\uB85C \uADF8\uB9B0\uB2E4. \uB370\uC2DC\uBCA8 \uD638\uB294 60\uB3C4\uB2E4. \uC7AC\uC0DD\uBC14 \uC0C9\uC740 \uADF8\uB824\uC9C4 \uC870\uC815\uAC12\uC758 \uD3C9\uADE0\uC5D0 \uAC00\uC7A5 \uAC00\uAE4C\uC6B4 \uC870\uC815\uAC12 \uC0C9\uC774\uB2E4. \uAC70\uB9AC\uAC00 \uAC19\uC73C\uBA74 \uB354 \uD070 \uAC12, \uADF8\uB798\uB3C4 \uAC19\uC73C\uBA74 \uD30C\uB780\uC0C9, \uADF8\uB2E4\uC74C \uBE68\uAC04\uC0C9, \uADF8\uB2E4\uC74C \uB178\uB780\uC0C9\uC774\uB2E4. \uC870\uC815\uAC12\uC774 \uC5C6\uC73C\uBA74 \uD770\uC0C9\uC774\uB2E4. \uCE21\uC815\uC774 \uC131\uACF5\uD55C \uC870\uC815\uAC12\uB9CC \uADF8 \uACE1 \uD30C\uC77C\uC758 sunoUrl \uC606 audioLevel\uC5D0 \uB0A8\uAE34\uB2E4. \uCE21\uC815\uC774 \uB05D\uB098\uBA74 \uADF8 \uAC12\uC744 \uADF8 \uACE1 \uACB0\uACFC\uCC3D \uBCF4\uC815\uAC12 \uCE78\uC5D0 \uBC14\uB85C \uB123\uB294\uB2E4. \uC0AC\uC5F0\uACE1\uACFC \uCEE4\uBC84\uACE1\uB3C4 EP \uACE1\uACFC \uAC19\uC740 \uCE78\uC774\uACE0 \uAC19\uC740 \uC800\uC7A5\uC774\uB2E4. \uACB0\uACFC\uCC3D \uC218\uB178 \uC8FC\uC18C \uC544\uB798 \uBCF4\uC815\uAC12\uC740 \uC9C1\uC811 \uACE0\uCE60 \uC218 \uC788\uB294 \uCE78\uC774\uB2E4. \uACE1, ACT, \uC0AC\uC5F0\uACE1, \uCEE4\uBC84\uACE1\uC774 \uAC19\uB2E4. \uC800\uC7A5\uC744 \uB204\uB974\uBA74 \uADF8 \uCE78\uC758 \uAE00\uC774 audioLevel\uB85C \uD30C\uC77C\uC5D0 \uB0A8\uB294\uB2E4. \uBE44\uC6B0\uACE0 \uC800\uC7A5\uD558\uBA74 \uD30C\uC77C\uC758 \uBCF4\uC815\uAC12\uB3C4 \uBE44\uC6B4\uB2E4. \uB2E4\uB978 \uC8FC\uC18C\uB85C \uBC14\uAFB8\uB4EF \uB2E4\uB978 \uBCF4\uC815\uAC12\uC744 \uB123\uACE0 \uC800\uC7A5\uD558\uBA74 \uADF8 \uAC12\uC774 \uB4E4\uC5B4\uAC04\uB2E4. \uC800\uC7A5 \uB4A4\uC5D0 \uC608\uC804 \uAC12\uC73C\uB85C \uB418\uB3CC\uB9AC\uC9C0 \uB9C8. \uAC12\uC744 \uCE58\uB294 \uC989\uC2DC \uC800\uC7A5\uD558\uC9C0 \uB9C8. \uD615\uC2DD\uC740 lufs=\uC22B\uC790;gain=\uC22B\uC790;peak=\uC22B\uC790 \uC774\uB2E4. \uD30C\uC77C\uACFC \uAC19\uC73C\uBA74 \uC587\uC740 \uAE08\uC0C9, \uB2E4\uB974\uBA74 \uBE68\uAC04\uC0C9, \uCE78\uC5D0\uB294 \uC788\uB294\uB370 \uD30C\uC77C\uC5D0 \uC5C6\uC73C\uBA74 \uD770\uC0C9\uC774\uB2E4. \uD30C\uC77C\uC744 \uC544\uC9C1 \uBABB \uC77D\uC5B4\uB3C4 \uB0B4\uC6A9\uC774 \uC788\uB294 \uCE78\uC740 \uD770\uC0C9\uC774\uB2E4. \uBE48 \uCE78\uC740 \uC9C0\uAE08 \uD14C\uB450\uB9AC\uB97C \uB454\uB2E4. \uBCF4\uC815\uAC12\uC774 \uD30C\uC77C\uC5D0 \uC548 \uB0A8\uC558\uB2E4\uACE0 \uB2E4\uB978 \uACB0\uACFC \uD56D\uBAA9 \uC800\uC7A5\uC744 \uB9C9\uC9C0 \uB9C8. \uC7AC\uC9C0 \uC54A\uC740 \uC9C0\uAE08 \uC7AC\uC0DD\uBAA9\uB85D \uBC16 \uACE1\uC758 \uBCF4\uC815\uAC12\uC740 \uB9CC\uB4E4\uC9C0 \uB9C8. \uACE0\uB978 \uCCAB \uACE1\uB9CC \uBA3C\uC800 \uC138 \uB2E8\uACC4\uB85C \uBCF4\uC815\uD558\uACE0 \uADF8 \uBCF4\uC815\uBCF8\uC744 \uC7AC\uC0DD\uD55C\uB2E4. \uADF8 \uC7AC\uC0DD\uC774 \uC2DC\uC791\uB41C \uB4A4\uC5D0\uB9CC \uC7AC\uC0DD\uBAA9\uB85D\uC758 \uB2E4\uB978 \uACE1 \uBCF4\uC815\uAC12\uC744 \uD55C \uACE1\uC529 \uC21C\uC11C\uB300\uB85C \uACC4\uC0B0\uD574 \uAC01 \uACE1 \uD30C\uC77C\uC758 audioLevel\uC5D0 \uBBF8\uB9AC \uC800\uC7A5\uD55C\uB2E4. \uBAA9\uB85D \uC804\uCCB4\uB97C \uBCF4\uC815\uD55C \uB4A4\uC5D0 \uCCAB \uACE1\uC744 \uD2C0\uC9C0 \uB9C8. \uCCAB \uACE1\uC774 \uC7AC\uC0DD\uB418\uAE30 \uC804\uC5D0 \uB2E4\uB978 \uACE1 \uBCF4\uC815\uC744 \uC2DC\uC791\uD558\uC9C0 \uB9C8. \uADF8 \uACC4\uC0B0\uC740 \uC18C\uB9AC\uB97C \uB0B4\uC9C0 \uC54A\uB294\uB2E4. \uBCF4\uC815 \uC911\uC778 \uACE1\uC744 \uC7AC\uC0DD \uC911\uC778 \uACE1\uACFC \uAC19\uC774 \uD2C0\uC9C0 \uB9C8. \uC774\uBBF8 audioLevel\uC774 \uC788\uB294 \uACE1\uC740 \uB2E4\uC2DC \uACC4\uC0B0\uD558\uC9C0 \uB9C8. \uB2E4\uC74C \uACE1\uC774 \uB098\uAE30 \uC804\uC5D0 \uC774\uC804 \uACE1\uC744 \uBA48\uCD98\uB2E4. \uBCF4\uC815\uAC12\uC740 \uADF8 \uACE1 \uD30C\uC77C\uC758 audioLevel\uB9CC \uC5F0\uB2E4. \uC218\uB178 \uC8FC\uC18C\uAC00 \uAC19\uB2E4\uACE0 \uB2E4\uB978 \uACE1\uC758 \uBCF4\uC815\uAC12\uC744 \uC774 \uCE78\uC5D0 \uB123\uC9C0 \uB9C8. \uC571\uC744 \uB098\uAC14\uB2E4\uAC00 \uB4E4\uC5B4\uC640\uB3C4 \uADF8 \uD30C\uC77C\uC758 \uCD5C\uC2E0 \uBCF4\uC815\uAC12\uC774 \uC774\uC804 \uAC12\uC73C\uB85C \uBC14\uB00C\uC9C0 \uB9C8. \uBCF4\uC815\uAC12\uC740 \uCE21\uC815\uD55C \uC74C\uB7C9\uC774\uB2E4. \uB9DE\uCD98 \uB4A4\uC758 -14\uB85C \uADF8 \uC22B\uC790\uB97C \uBC14\uAFB8\uC9C0 \uB9C8. \uC218\uB178 \uC8FC\uC18C\uAC00 \uAC19\uB2E4\uACE0 \uB2E4\uB978 \uACE1\uC758 \uBCF4\uC815\uAC12\uC744 \uB123\uC9C0 \uB9C8. \uACE1 \uC804\uCCB4 \uC800\uC7A5\uC774 \uD654\uBA74\uC5D0\uC11C \uBC29\uAE08 \uC800\uC7A5\uD55C \uBCF4\uC815\uAC12\uC744 \uC774\uC804 \uAC12\uC73C\uB85C \uBC14\uAFB8\uC9C0 \uB9C8. 재생할 때 주크박스는 그 곡 파일의 수노 주소, 음원분석값, 음원보정값을 읽는다. 분석값이나 보정값이 비어 있으면 그 칸을 채워 바로 그 파일에 저장한다.";
