  const matchRule = "\uACB0\uACFC\uB300\uC870=\uACB0\uACFC\uCC3D \uD56D\uBAA9\uC5D0 \uB0B4\uC6A9\uC774 \uC788\uC744 \uB54C\uB9CC \uADF8 \uCE78\uC744 \uC9C0\uAE08 \uC5F0 \uACE1, ACT, \uC0AC\uC5F0\uACE1, \uCEE4\uBC84\uACE1 \uD30C\uC77C\uACFC \uB300\uC870\uD55C\uB2E4. \uC0AC\uC5F0\uACE1\uACFC \uCEE4\uBC84\uACE1\uB3C4 \uACE1, ACT\uC640 \uAC19\uC740 \uACF5\uD1B5 \uC0C9\uC774\uB2E4. \uB0B4\uC6A9\uC774 \uAC19\uACE0 \uC800\uC7A5\uB41C \uCE78\uC740 \uD14C\uB450\uB9AC\uB97C \uC5F0\uD55C \uAE08\uC0C9\uC73C\uB85C \uB454\uB2E4. \uB0B4\uC6A9\uC774 \uC788\uB294\uB370 \uD30C\uC77C\uACFC \uB2E4\uB974\uBA74 \uD14C\uB450\uB9AC\uB97C \uBE68\uAC04\uC0C9\uC73C\uB85C \uB454\uB2E4. \uB0B4\uC6A9\uC774 \uC788\uB294\uB370 \uADF8 \uCE78\uC774 \uD30C\uC77C\uC5D0 \uC544\uC9C1 \uC5C6\uC73C\uBA74 \uD14C\uB450\uB9AC\uB97C \uD770\uC0C9\uC73C\uB85C \uB454\uB2E4. \uB0B4\uC6A9\uC774 \uC5C6\uB294 \uCE78\uC758 \uD14C\uB450\uB9AC\uB294 \uC9C0\uAE08 \uADF8\uB300\uB85C \uB454\uB2E4. \uD30C\uC77C\uC744 \uC544\uC9C1 \uBABB \uC77D\uC5B4\uB3C4 \uB0B4\uC6A9\uC774 \uC788\uB294 \uCE78\uC740 \uD770\uC0C9\uC774\uB2E4. \uB300\uC870\uD55C\uB2E4\uACE0 \uD655\uC815 \uAE00\uC744 \uBC14\uAFB8\uC9C0 \uB9C8. \uC218\uB178 URL, \uADF8 \uC544\uB798 \uBCF4\uC815\uAC12, \uC720\uD29C\uBE0C URL\uB3C4 \uB0B4\uC6A9\uC774 \uC788\uC744 \uB54C\uB9CC \uAC19\uC740 \uAE30\uC900\uC73C\uB85C \uD14C\uB450\uB9AC\uB97C \uB454\uB2E4. \uC8FC\uC18C\uB098 \uBCF4\uC815\uAC12\uC774 \uD30C\uC77C\uACFC \uAC19\uC73C\uBA74 \uC5F0\uD55C \uAE08\uC0C9, \uD30C\uC77C\uACFC \uB2E4\uB974\uBA74 \uBE68\uAC04\uC0C9, \uCE78\uC5D0\uB294 \uC788\uB294\uB370 \uD30C\uC77C\uC5D0 \uC5C6\uC73C\uBA74 \uD770\uC0C9\uC774\uB2E4. \uBE48 \uCE78\uC740 \uC9C0\uAE08 \uD14C\uB450\uB9AC\uB97C \uB454\uB2E4. \uACB0\uACFC\uCC3D\uC5D0 \uBCF4\uC774\uB294 \uAE00\uC740 \uC9C0\uAE08 \uC5F0 \uACE1 \uD30C\uC77C\uC758 \uAE00\uC774\uB2E4. \uC800\uC7A5\uCE78\uC758 \uC774\uC804 \uAE00\uB85C \uACE1 \uD30C\uC77C\uC744 \uB36E\uC9C0 \uB9C8. \uD655\uC815\uB41C \uACE1, \uD655\uC815\uB41C ACT, \uD50C\uB808\uC774\uB9AC\uC2A4\uD2B8 \uACB0\uACFC \uAE00\uC740 \uC0AC\uC6A9\uC790\uAC00 \uADF8 \uCE78\uC744 \uC9C1\uC811 \uACE0\uCE5C \uAC83\uB9CC \uBC14\uAFBC\uB2E4. \uC124\uBA85\uB780\uC744 \uB300\uC870\uD560 \uB54C\uB294 \u2501\u2501 \uC0AC\uC774\uC5D0 \uCD94\uAC00\uB85C \uBD99\uC740 \uAC00\uC0AC\uCE78\uC744 \uBE7C\uACE0 \uBCF8\uBB38\uB9CC \uBE44\uAD50\uD55C\uB2E4. ACT \uD50C\uB808\uC774\uB9AC\uC2A4\uD2B8 \uC124\uBA85\uB780\uC758 \uD2B8\uB799\uB9AC\uC2A4\uD2B8\uB3C4 \uADF8 \uCE78\uC5D0\uC11C \uBE7C\uACE0 \uBCF8\uBB38\uB9CC \uBE44\uAD50\uD55C\uB2E4. \uADF8 \uAD6C\uAC04\uC774 \uB2E4\uB974\uB2E4\uB294 \uC774\uC720\uB9CC\uC73C\uB85C \uBE68\uAC04\uC0C9\uC73C\uB85C \uB450\uC9C0 \uB9C8. \uBCF8\uBB38\uC740 \uBC14\uAFB8\uC9C0 \uB9C8.";
