  const current = "관리자입장=잠금 상태에서는 설정 버튼이 보이지 않는다. 메인 심볼을 3초 누르면 그 방문만 설정 버튼이 보인다. 최고 관리자 기기는 접속하면 잠금이 풀린 상태다. 등록되지 않은 기기를 관리자로 올리지 마.";
  return String(text || "").replace(old, next).replace(current, next);
